      END_STATE();
    case 7:
      if (lookahead == 'h') ADVANCE(9);
      END_STATE();
    case 8:
      if (lookahead == 'e') ADVANCE(10);
      END_STATE();
    case 9:
      ACCEPT_TOKEN(anon_sym_each);
      END_STATE();
    case 10:
      ACCEPT_TOKEN(anon_sym_else);
